type ActivityEvent={at:number;kind:'save'|'create'|'delete'|'backup'|'restore'|'publish'};
function readActivity():ActivityEvent[]{try{const raw=localStorage.getItem(ACTIVITY);if(!raw)return[];const cutoff=Date.now()-30*24*60*60*1000;const parsed=JSON.parse(raw);return Array.isArray(parsed)?parsed.filter((event):event is ActivityEvent=>Number.isFinite(event?.at)&&event.at>=cutoff&&['save','create','delete','backup','restore','publish'].includes(event.kind)).slice(-100):[]}catch{return[]}}
