 useEffect(()=>{if(!open)return;dialogRef.current?.focus();const onPointerDown=(event:PointerEvent)=>{const target=event.target as Node;if(!dialogRef.current?.contains(target)&&!triggerRef.current?.contains(target))setOpen(false)};const onKeyDown=(event:KeyboardEvent)=>{if(event.key==='Escape')setOpen(false)};document.addEventListener('pointerdown',onPointerDown);document.addEventListener('keydown',onKeyDown);return()=>{document.removeEventListener('pointerdown',onPointerDown);document.removeEventListener('keydown',onKeyDown);triggerRef.current?.focus()}},[open]);
