 const [newCollectionName,setNewCollectionName]=useState('');const [newCollectionSlug,setNewCollectionSlug]=useState('');const [newCollectionSlugManual,setNewCollectionSlugManual]=useState(false);const [newCollectionKind,setNewCollectionKind]=useState<'gallery'|'content'>('content');const [newCollectionLayout,setNewCollectionLayout]=useState<'grid'|'list'|'masonry'>('grid');const [newCollectionLoading,setNewCollectionLoading]=useState<'pagination'|'show-more'>('show-more');
 const [tagDrafts,setTagDrafts]=useState<Record<string,string>>({});
 const [cloudConnected,setCloudConnected]=useState<boolean|null>(null);const [cloudAccounts,setCloudAccounts]=useState<{id:string;name:string}[]>([]);const [cloudAccount,setCloudAccount]=useState('');const [cloudProjects,setCloudProjects]=useState<{name:string;productionBranch:string}[]>([]);const [cloudProject,setCloudProject]=useState('');const [deploymentUrl,setDeploymentUrl]=useState('');
 const [migrationBackupFile,setMigrationBackupFile]=useState(initialMigrationBackupFile);
 const [migrationDraftBackupFile,setMigrationDraftBackupFile]=useState(initialMigrationDraftBackupFile);
 function recordActivity(kind:ActivityEvent['kind']){const next=[...activityRef.current,{at:Date.now(),kind}].filter(event=>event.at>=Date.now()-30*24*60*60*1000).slice(-100);activityRef.current=next;setActivity(next);try{localStorage.setItem(ACTIVITY,JSON.stringify(next))}catch{}}
 function navigate(section:string,replace=false,discardPrevious=false){if(section===activeRef.current){setMenuOpen(false);return}if(replace){if(discardPrevious)navigationStackRef.current.pop()}else navigationStackRef.current=[...navigationStackRef.current.slice(-99),activeRef.current];activeRef.current=section;if(replace)window.history.replaceState({...window.history.state,v2Dashboard:section},'');else window.history.pushState({...window.history.state,v2Dashboard:section},'');setActive(section);setMessage('');setMenuOpen(false)}
 function fallbackFor(section:string){if(section.startsWith('item:')){const item=data.items.find(value=>section===`item:${value.id}`);return item?`collection:${item.collectionId}`:'collections'}if(section.startsWith('page:'))return'pages';if(section.startsWith('collection-settings:'))return`collection:${section.slice('collection-settings:'.length)}`;if(section.startsWith('collection:')||section==='collection:new')return'collections';return'overview'}
 function navigateBack(){if(navigationStackRef.current.length){window.history.back();return}navigate(fallbackFor(activeRef.current))}
 useEffect(()=>{const current={...window.history.state,v2Dashboard:activeRef.current};window.history.replaceState(current,'');const onPopState=(event:PopStateEvent)=>{setMessage('');const destination=typeof event.state?.v2Dashboard==='string'?event.state.v2Dashboard:'overview';const previous=navigationStackRef.current.at(-1);if(previous===destination)navigationStackRef.current.pop();else if(destination!==activeRef.current)navigationStackRef.current=[...navigationStackRef.current.slice(-99),activeRef.current];activeRef.current=destination;setActive(destination);setMenuOpen(false)};window.addEventListener('popstate',onPopState);return()=>window.removeEventListener('popstate',onPopState)},[]);
 useEffect(()=>{if(!menuOpen)return;const navigation=navigationRef.current;const previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';const focusable=()=>Array.from(navigation?.querySelectorAll<HTMLElement>('a[href],button:not(:disabled)')??[]);focusable()[0]?.focus();const onKeyDown=(event:KeyboardEvent)=>{if(event.key==='Escape'){event.preventDefault();setMenuOpen(false);menuToggleRef.current?.focus();return}if(event.key==='Tab'){const elements=focusable();if(!elements.length)return;const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}};document.addEventListener('keydown',onKeyDown);return()=>{document.removeEventListener('keydown',onKeyDown);document.body.style.overflow=previousOverflow;if(navigation?.contains(document.activeElement))menuToggleRef.current?.focus()}},[menuOpen]);
 useEffect(()=>{const update=()=>setOnline(navigator.onLine);window.addEventListener('online',update);window.addEventListener('offline',update);return()=>{window.removeEventListener('online',update);window.removeEventListener('offline',update)}},[]);
 useEffect(()=>{const update=()=>{const saved=readNativeConflict<unknown>();if(!saved)return;const checked=ContentSchema.safeParse(saved.content);if(checked.success)setConflict({content:checked.data,sha:saved.sha})};window.addEventListener('studio-native-project-conflict',update);return()=>window.removeEventListener('studio-native-project-conflict',update)},[]);
